  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- ecic-highveld (researched)
UPDATE businesses SET description = 'ECIC is the Export Credit Insurance Corporation of South Africa, a state-owned national export credit agency established in 2001 under the Export Credit and Foreign Investments Insurance Act. Based in Highveld, Centurion, it provides political and commercial risk insurance to South African exporters of capital goods and related services, with a particular focus on Africa and other emerging markets.

Beyond export credit cover, ECIC offers investment insurance for South African entities investing in foreign countries, and a Small and Medium Transactions programme tailored to smaller exporters. As a self-sustained, licensed non-life insurer and authorised Financial Services Provider, ECIC also works in partnership with Afreximbank, extending its reach as an export risk partner for South African businesses trading into markets that commercial insurers may see as too risky to cover alone.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://ecic.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'ecic-highveld' AND description = 'ECIC is the Export Credit Insurance Corporation of South Africa SOC Ltd, a state-owned national export credit agency established in 2001 that provides political and commercial risk insurance to South African exporters of capital goods and related services, with a particular focus on Africa and other emerging markets.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
